import{z as i,x as A,o as t,c as l,q as s,j as B,D as r,d as n,s as o,S as P,b as e}from"./chunks/framework.C8m1ZpeB.js";const S=JSON.parse('{"title":"BQP 直觉","description":"","frontmatter":{"title":"BQP 直觉","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/bqp-intuition.md","filePath":"cs/bqp-intuition.md","lastUpdated":1791063341000}'),p={name:"cs/bqp-intuition.md"};function d(u,a,h,C,m,Q){const E=A("Mermaid");return t(),l("div",null,[a[2]||(a[2]=s('<h1 id="bqp-直觉" tabindex="-1">BQP 直觉 <a class="header-anchor" href="#bqp-直觉" aria-label="Permalink to &quot;BQP 直觉&quot;">​</a></h1><div class="epigraph"><p>BQP 是量子电路多项式规模、测量错误可放大的语言类。它含 BPP，被相信不含 NP 完全问题，却能因子分解。</p><footer>—— 据 Bernstein and Vazirani；Shor；Watrous；Arora and Barak 整理</footer></div><p>上一课<a href="/cs/one-way-functions-avg">单向函数</a> 停在经典平均。缺口是给量子多项式类一个<strong>位置</strong>，不是量子力学课，也不是大模型。BQP：均匀多项式量子电路，接受概率与 BPP 同类缝隙。Shor：因子在 BQP。NPC 是否在 BQP 未知，普遍不信。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>量子电路：幺正门 + 测量。状态空间 \\(2^n\\) 维，但描述必须均匀生成。BPP \\(\\subseteq\\) BQP：经典硬币可模拟。BQP \\(\\subseteq\\) PSPACE：用多项式空间算振幅递归（对指数维求和要小心，但配置可递归）。与 NP：无已知把 SAT 放进 BQP 的算法；Grover 是平方加速，不是指数。</p><p>广义 Church–Turing：若物理量子可实现，则「有效」大于 BPP。本课不争论物理。</p><h3 id="不是「量子-指数并行」" tabindex="-1">不是「量子 = 指数并行」 <a class="header-anchor" href="#不是「量子-指数并行」" aria-label="Permalink to &quot;不是「量子 = 指数并行」&quot;">​</a></h3><p>叠加不是 \\(2^n\\) 份经典答案的免费读取。干涉必须设计；测量只给一帧。把 BQP 写成 PSPACE 的子集已经限制了「全能」。</p><p><span class="marginnote">Bernstein–Vazirani 定义 BQP。Shor 1994 因子与离散对数。Watrous 的量子复杂度综述。本栏不重写量子力学公理，只定位类。</span></p><p><span class="marginnote">术语翻译：<strong>BQP</strong>=「量子计算机在多项式时间内能解、错误率可压小」的问题类，地位与 BPP 对应——只是把随机硬币换成了量子门与测量。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>画包含：\\(P\\subseteq BPP\\subseteq BQP\\subseteq PSPACE\\)，NP 旁支。点名 Shor 击穿的是因子 / 离散对数假设，不是 OWF 全体（格、后课 LWE 仍候选）。不要给量子门清单当主线。</p>',12)),(t(),B(P,null,{default:r(()=>[o(E,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20BPP%5B%22BPP%22%5D%20--%3E%20BQP%5B%22BQP%20%E9%87%8F%E5%AD%90%E5%A4%9A%E9%A1%B9%E5%BC%8F%22%5D%0A%20%20BQP%20--%3E%20PSP%5B%22PSPACE%22%5D%0A%20%20NP%5B%22NP%22%5D%20-.-%3E%20BQP%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("h2",{id:"机制",tabindex:"-1"},[n("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=e("p",null,"复杂性补层到此：时间、空间、随机、交互、PCP、电路、参数、平均、量子，都挂在 TM / 电路模型上。下一单元换尺子：Shannon 信息。BQP 不进入那一单元的公式。",-1)),a[5]||(a[5]=e("p",null,"因子在 BQP 而未知在 P，是「BQP 可能真大于 BPP」的最强课堂证据，仍非证明。",-1)),a[6]||(a[6]=e("p",null,"Grover 把无结构搜索从 \\(N\\) 降到 \\(\\sqrt{N}\\)，仍指数于比特数。Shor 用周期发现打因子与离散对数，不打一般 NPC。QMA 是量子 NP 类似物，本课不进。把 BQP 画在 \\(PSPACE\\) 内，已经禁止「读出全部振幅」。复杂性单元到此结束。",-1)),a[7]||(a[7]=e("p",null,"同样说「并行」，经典随机、量子叠加、并行机各指什么？",-1)),(t(),B(P,null,{default:r(()=>[o(E,{id:"mermaid-50",class:"mermaid",graph:"flowchart%20TD%0A%20%20C%5B%22%E7%BB%8F%E5%85%B8%E9%9A%8F%E6%9C%BA%EF%BC%9A%E4%B8%80%E6%AC%A1%E6%8A%BD%E4%B8%80%E6%9D%A1%E8%B7%AF%22%5D%20--%3E%20CR%5B%22%E9%87%8D%E8%B7%91%E5%A4%9A%E6%AC%A1%E6%8A%95%E7%A5%A8%22%5D%0A%20%20Q%5B%22%E9%87%8F%E5%AD%90%E5%8F%A0%E5%8A%A0%EF%BC%9A%E5%90%8C%E6%97%B6%E6%90%BA%E5%B8%A6%E5%85%A8%E9%83%A8%E8%B7%AF%E5%BE%84%E7%9A%84%E6%8C%AF%E5%B9%85%22%5D%20--%3E%20I%5B%22%E8%AE%BE%E8%AE%A1%E5%B9%B2%E6%B6%89%E8%AE%A9%E9%94%99%E8%B7%AF%E7%9B%B8%E6%B6%88%22%5D%0A%20%20I%20--%3E%20M%5B%22%E6%B5%8B%E9%87%8F%E5%8F%AA%E7%BB%99%E4%B8%80%E4%B8%AA%E7%AD%94%E6%A1%88%22%5D%0A%20%20PAR%5B%22%E5%B9%B6%E8%A1%8C%E6%9C%BA%EF%BC%9A%E7%9C%9F%E5%90%8C%E6%97%B6%E7%AE%97%22%5D%20--%3E%20OUT%5B%22%E4%BD%86%E5%86%85%E5%AD%98%E4%B8%8E%E7%AE%97%E5%8A%9B%E6%8C%89%E9%97%AE%E9%A2%98%E6%8C%87%E6%95%B0%E6%B6%A8%22%5D%0A"})]),fallback:r(()=>[...a[1]||(a[1]=[n(" Loading... ",-1)])]),_:1})),a[8]||(a[8]=s('<p><span class="marginnote">数字实例：\\(n=100\\) 时状态空间 \\(2^{100}\\) 维，但描述电路只需多项式个门；测量后你只拿到 1 个比特串。Grover 在 \\(N=2^{100}\\) 上也只把 \\(10^{30}\\) 量级的步数压成 \\(10^{15}\\)——平方根远不是「一步查完」。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不推导 Shor，不引入量子纠错、QMA。不把量子退火当 BQP。后课默认：BQP 是量子多项式类，含因子，不自动吞 NP。下一课信源编码定理，接<a href="/cs/entropy-bits">熵</a>。</p><p>BQP 含因子分解，被画在 PSPACE 内，且不默认含 NPC。广义 Church–Turing 是否要扩到量子，是物理与模型的交界，本课只定位类。信息论单元不再用振幅。</p><p><span class="marginnote">常见误区：初学者容易以为「量子计算机=对所有问题指数加速」。实际上加速依赖可设计的干涉结构：因子的周期结构适合 Shor；无结构搜索只有平方加速；对 NP 完全问题，学界普遍相信没有指数加速。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>BQP：多项式量子电路 + 可放大错误。</li><li>\\(BPP\\subseteq BQP\\subseteq PSPACE\\)；Shor 把因子放进来。</li><li>叠加不是免费指数；NPC 不默认在 BQP。</li><li>出处：Bernstein and Vazirani；Shor；Watrous。</li></ul>',7))])}const q=i(p,[["render",d]]);export{S as __pageData,q as default};
